// Prisma: Strict, deeply typed without string literals
const user = await prisma.user.findUnique({
  where: { email: 'alex@example.com' },
  include: {
    posts: { where: { published: true } },
    profile: true
  }
});

// TypeORM: Relies on string relations or query builders
const userRepo = dataSource.getRepository(User);
const user = await userRepo.findOne({
  where: { email: 'alex@example.com' },
  relations: ['posts', 'profile'] // string literals prone to typos
});
